#!/usr/bin/env node
// Regenerates src/data/zugLocalities.generated.ts from the official Swiss
// locality list (swisstopo "Amtliches Ortschaftenverzeichnis", CSV LV95).
// Manual maintenance tool: never run during the build or in CI.
//
//   curl -LO https://data.geo.admin.ch/ch.swisstopo-vd.ortschaftenverzeichnis_plz/ortschaftenverzeichnis_plz/ortschaftenverzeichnis_plz_2056.csv.zip
//   unzip ortschaftenverzeichnis_plz_2056.csv.zip
//   node scripts/municipality-data/build-localities.mjs AMTOVZ_CSV_LV95/AMTOVZ_CSV_LV95.csv
//
// Review the diff of the generated file before committing it.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";

const SOURCE_URL =
  "https://data.geo.admin.ch/ch.swisstopo-vd.ortschaftenverzeichnis_plz/ortschaftenverzeichnis_plz/ortschaftenverzeichnis_plz_2056.csv.zip";
const OUTPUT = new URL("../../src/data/zugLocalities.generated.ts", import.meta.url);
const EXPECTED_HEADER = [
  "Ortschaftsname", "PLZ4", "Zusatzziffer", "ZIP_ID", "Gemeindename", "BFS-Nr",
  "Kantonskürzel", "Adressenanteil", "E", "N", "Sprache", "Validity",
];
const CANTON = "ZG";

const csvPath = process.argv[2];
if (!csvPath) {
  console.error("usage: build-localities.mjs <AMTOVZ_CSV_LV95.csv>");
  process.exit(2);
}

const raw = readFileSync(csvPath);
const sha256 = createHash("sha256").update(raw).digest("hex");
const lines = raw.toString("utf8").replace(/^﻿/, "").split(/\r?\n/).filter(Boolean);
const header = lines[0].split(";");
if (header.join(";") !== EXPECTED_HEADER.join(";")) {
  console.error(`unexpected CSV header: ${lines[0]}`);
  process.exit(1);
}

// One locality = postcode + Zusatzziffer; its rows list each municipality's
// share of the locality's addresses. Kantonskürzel is the municipality's canton.
const localities = new Map();
for (const line of lines.slice(1)) {
  const cells = line.split(";");
  const row = Object.fromEntries(header.map((name, i) => [name, cells[i]]));
  const key = `${row.PLZ4}-${row.Zusatzziffer}`;
  const locality = localities.get(key) ?? {
    postcode: row.PLZ4,
    suffix: row.Zusatzziffer,
    locality: row.Ortschaftsname,
    rows: [],
  };
  locality.rows.push({
    bfs: Number(row["BFS-Nr"]),
    canton: row["Kantonskürzel"],
    share: Number.parseFloat(row.Adressenanteil),
  });
  localities.set(key, locality);
}

const round = (n) => Math.round(n * 1000) / 1000;
const result = [...localities.values()]
  .filter((l) => l.rows.some((r) => r.canton === CANTON))
  .map((l) => {
    const zug = l.rows.filter((r) => r.canton === CANTON);
    const zugShare = zug.reduce((sum, r) => sum + r.share, 0);
    return {
      postcode: l.postcode,
      locality: l.locality,
      main: l.suffix === "00",
      municipalities: zug
        .map(({ bfs, share }) => ({ bfs, share: round(share) }))
        .sort((a, b) => b.share - a.share || a.bfs - b.bfs),
      outsideShare: round(Math.max(0, 100 - zugShare)),
    };
  })
  .sort((a, b) => a.postcode.localeCompare(b.postcode) || Number(b.main) - Number(a.main) || a.locality.localeCompare(b.locality));

const today = new Date().toISOString().slice(0, 10);
const body = `// GENERATED by scripts/municipality-data/build-localities.mjs — do not edit by hand.
// Source: ${SOURCE_URL}
// Generated: ${today} · CSV SHA-256: ${sha256}
// Localities with at least one address in canton ${CANTON}. Shares are % of the
// locality's addresses; outsideShare is the part in other cantons.
import type { ZugLocality } from "./types";

export const ZUG_LOCALITIES: readonly ZugLocality[] = [
${result.map((l) => `  ${JSON.stringify(l)},`).join("\n")}
];
`;
writeFileSync(OUTPUT, body);
console.log(`wrote ${result.length} localities to ${OUTPUT.pathname}`);
